// ─── CONFIGURATION ──────────────────────────────────────────────
// Edit these values to match your project and preferences:
// ───────────────────────────────────────────────────────────────────
const config = {
  repo:           'owner/repo',         // GitHub repository (owner/name)
  language:       'EN',                 // Summary language: 'EN' or 'FR'
  claudeApiKey:   'sk-ant-...',         // Anthropic Claude API key
  discordWebhook: '',                   // Discord webhook URL (leave empty to skip)
  slackWebhook:   '',                   // OR Slack webhook URL
};
// ───────────────────────────────────────────────────────────────────

const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

return [{
  json: {
    since:         weekAgo.toISOString(),
    until:         now.toISOString(),
    sinceDate:     weekAgo.toISOString().split('T')[0],
    untilDate:     now.toISOString().split('T')[0],
    repo:          config.repo,
    language:      config.language,
    claudeApiKey:  config.claudeApiKey,
    discordWebhook: config.discordWebhook,
    slackWebhook:  config.slackWebhook,
  }
}];

// ─── Classify all items and build a Claude prompt ───
const items = $input.all();
const config = $node['Config'].json;

const commits = [];
const issues = [];
const prs = [];

for (const item of items) {
  const d = item.json;
  if (d.sha && d.commit) {
    // GitHub commit object
    commits.push({
      sha: d.sha.substring(0, 7),
      author: d.commit?.author?.name || d.author?.login || 'unknown',
      message: (d.commit?.message || '').split('\n')[0],
      date: d.commit?.author?.date?.split('T')[0] || '',
    });
  } else if (d.pull_request && d.title) {
    // PR from search results
    prs.push({
      number: d.number,
      title: d.title,
      author: d.user?.login || 'unknown',
      state: d.state,
      merged: d.pull_request?.merged_at || d.closed_at,
      html_url: d.html_url,
      labels: (d.labels || []).map(l => l.name),
    });
  } else if (d.html_url && d.title && !d.pull_request) {
    // Issue (from issues endpoint; PRs also have html_url so we exclude them)
    issues.push({
      number: d.number,
      title: d.title,
      author: d.user?.login || 'unknown',
      state: d.state,
      closed_at: d.closed_at,
      html_url: d.html_url,
      labels: (d.labels || []).map(l => l.name),
    });
  }
}

// ── Build prompt ────────────────────────────────────────────
const lang = config.language === 'FR' ? 'French' : 'English';

const prompt = `You are a technical writing assistant. Write a weekly development summary in ${lang} for the GitHub repository **${config.repo}**.

Cover the week from ${config.sinceDate} to ${config.untilDate}.

Write in a clear, engaging, narrative style — not a bullet list. Group related changes thematically. Mention contributors by name.

Here is the raw activity data:

--- COMMITS (${commits.length}) ---
${JSON.stringify(commits, null, 2)}

--- CLOSED ISSUES (${issues.length}) ---
${JSON.stringify(issues, null, 2)}

--- MERGED PRs (${prs.length}) ---
${JSON.stringify(prs, null, 2)}

---

Output the summary in pure markdown. Start with a heading "## Weekly Dev Summary — …" and the date range. End with a section "## Stats" that shows: Commits, Issues closed, PRs merged, Unique contributors.`;

return [{
  json: {
    prompt: prompt,
    repo: config.repo,
    sinceDate: config.sinceDate,
    untilDate: config.untilDate,
    language: config.language,
    stats: {
      commits: commits.length,
      issues: issues.length,
      prs: prs.length,
      uniqueAuthors: new Set([
        ...commits.map(c => c.author),
        ...issues.map(i => i.author),
        ...prs.map(p => p.author),
      ]).size,
    }
  }
}];

// ─── Call Claude API to generate the narrative summary ───
const inputData = $input.first().json;
const apiKey = $node['Config'].json['claudeApiKey'];

if (!apiKey || apiKey === 'sk-ant-...') {
  throw new Error('Claude API key not configured. Edit the Config node.');
}

const body = {
  model: 'claude-sonnet-4-20250514',
  max_tokens: 4096,
  messages: [
    { role: 'user', content: inputData.prompt }
  ]
};

let response;
try {
  response = await $http.post(
    'https://api.anthropic.com/v1/messages',
    body,
    {
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      }
    }
  );
} catch (error) {
  throw new Error(
    'Claude API call failed: ' +
    (error.response?.data?.error?.message || error.message || JSON.stringify(error))
  );
}

const summary = response?.data?.content?.[0]?.text;

if (!summary) {
  throw new Error('Claude returned an empty response.');
}

return [{
  json: {
    summary: summary,
    repo: inputData.repo,
    sinceDate: inputData.sinceDate,
    untilDate: inputData.untilDate,
    stats: inputData.stats,
  }
}];
